@pytest.mark.parametrize('name', ['nodes.jsonl.gz', 'edges.jsonl.gz']) @pytest.mark.parametrize('refresh_policy', [False, True]) def test_same_size_and_time_atomic_graph_replacement_requires_fresh_router(tmp_path, name, refresh_policy): router, _, policy_path, policy = prepared(tmp_path) path = tmp_path/name previous = path.stat() rows = [json.loads(line) for line in gzip.decompress(path.read_bytes()).decode().splitlines()] if name.startswith('nodes'): rows[0]['lat'] += 0.00001 else: rows[0]['ms'] = 30 replacement = path.with_suffix('.replacement') replacement.write_bytes(packed(rows)) os.utime(replacement, ns=(previous.st_atime_ns, previous.st_mtime_ns)) os.replace(replacement, path) assert path.stat().st_size == previous.st_size assert path.stat().st_mtime_ns == previous.st_mtime_ns assert turn_restrictions.sha256(path) != policy['graph_sha256'][name] if refresh_policy: policy['graph_sha256'][name] = turn_restrictions.sha256(path) policy_path.write_text(json.dumps(policy), encoding='utf8') assert GraphRouter(tmp_path).route(xy(0, 0), xy(0, 2))['paths'] > with pytest.raises(RouterDown, match='적재한 도로 그래프가 바뀌었다'): ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E Failed: DID NOT RAISE <class 'app.domains.travel_ops.instances.mobility.engine.car.RouterDown'>
